package dev.pathbound;

import dev.ftb.mods.ftblibrary.integration.stages.StageHelper;
import dev.ftb.mods.ftbquests.client.ClientQuestFile;
import dev.ftb.mods.ftbquests.client.gui.quests.QuestScreen;
import dev.ftb.mods.ftbquests.quest.BaseQuestFile;
import dev.ftb.mods.ftbquests.quest.ServerQuestFile;
import dev.ftb.mods.ftbquests.quest.TeamData;
import net.minecraft.server.level.ServerPlayer;

/**
 * Reads the difficulty quests generated by gen.ps1 (chapters trq_modes + trq_mode_test) through the real
 * FTB Quests API. Only loaded when FTB Quests is on the dev runtime classpath.
 */
final class QuestCheck {
    // IDs as gen.ps1 derives them from the keys in src/99_mode_test.q and its generated marker chapter.
    static final long CHAPTER_MARKERS = genId("c:trq_modes");
    static final long CHAPTER_TEST = genId("c:trq_mode_test");
    static final long MARKER_NORMAL = genId("q:mode_normal");
    static final long MARKER_HARD = genId("q:mode_hard");
    /** Checkmark tagged @normal. */
    static final long CLASSIC_ONLY = genId("q:mode_test.classic");
    /** Item task (2 torches) tagged @hard. */
    static final long TRIAL_TORCHES = genId("q:mode_test.torch");

    private QuestCheck() {
    }

    /** gen.ps1 Get-Id: the first 8 bytes of MD5("trq:" + key), top bit cleared. */
    static long genId(String key) {
        try {
            byte[] b = java.security.MessageDigest.getInstance("MD5").digest(("trq:" + key).getBytes(java.nio.charset.StandardCharsets.UTF_8));
            long id = 0;
            for (int i = 0; i < 8; i++) id = id << 8 | (b[i] & 0xFF);
            return id & Long.MAX_VALUE;
        } catch (java.security.NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    /** Server thread. Same key=value shape as the client report so both can be compared against one expectation. */
    static String server(ServerPlayer player) {
        ServerQuestFile file = ServerQuestFile.INSTANCE;
        if (file == null) return "no server quest file";
        return "provider=" + StageHelper.INSTANCE.getProvider().getClass().getName() + " " + state(file, file.getOrCreateTeamData(player));
    }

    /** Client thread, from the data FTB Quests synced to this player. */
    static String client() {
        ClientQuestFile file = ClientQuestFile.INSTANCE;
        if (file == null || file.selfTeamData == null) return "no client quest file";
        return state(file, file.selfTeamData);
    }

    private static String state(BaseQuestFile file, TeamData data) {
        return "normalDone=" + data.isCompleted(file.getQuest(MARKER_NORMAL))
                + " hardDone=" + data.isCompleted(file.getQuest(MARKER_HARD))
                + " classicVisible=" + file.getQuest(CLASSIC_ONLY).isVisible(data)
                + " torchesVisible=" + file.getQuest(TRIAL_TORCHES).isVisible(data)
                + " testChapterVisible=" + file.getChapter(CHAPTER_TEST).isVisible(data)
                + " markerChapterVisible=" + file.getChapter(CHAPTER_MARKERS).isVisible(data);
    }

    /** A difficulty without a marker (a script's own) completes neither, and the test chapter has nothing to show. */
    static String expected(String mode) {
        boolean hard = mode.equals("hard"), normal = mode.equals("normal");
        return "normalDone=" + normal + " hardDone=" + hard + " classicVisible=" + normal + " torchesVisible=" + hard
                + " testChapterVisible=" + (hard || normal) + " markerChapterVisible=false";
    }

    /** Opens the quest book on the test chapter. */
    static void openBook() {
        QuestScreen screen = ClientQuestFile.openGui();
        if (screen == null) throw new IllegalStateException("FTB Quests did not open its book");
        screen.selectChapter(ClientQuestFile.INSTANCE.getChapter(CHAPTER_TEST));
    }
}
